## Design Note

The decoder is a character-by-character finite-state machine. Each character is processed exactly once (O(1) per char, O(n) total). A list-of-chars buffer accumulates the current top-level value text; at value completion, `json.loads` decodes it in one shot. Container nesting is tracked via a stack of (type, sub-state) tuples. Top-level numbers/literals require a terminator character to confirm completion. No re-scanning of buffered text occurs, giving linear total work regardless of chunking. Single-threaded per connection; no locks.

### solution.py

```python
"""Incremental JSON stream splitter for log ingestion (Python 3.12, stdlib only)."""

from __future__ import annotations

import json
from typing import Any


class JSONStreamError(ValueError):
    """Base error for JSON stream decoding problems."""

    def __init__(self, msg: str = "") -> None:
        super().__init__(msg)
        self.offset: int = 0


class IncompleteJSONError(JSONStreamError):
    """Raised when close() is called with an unfinished value."""


class BufferLimitError(JSONStreamError):
    """Raised when a top-level value exceeds max_buffer characters."""


_WS = frozenset(" \t\n\r")
_HEX = frozenset("0123456789abcdefABCDEF")

# Number sub-states
# AM=after minus, AZ=after zero, AI=after int, FS=fraction start (no digits),
# F=fraction with digits, AE=after e/E, ES=after exponent sign, E=in exponent digits
_NUM_VALID = frozenset({"AZ", "AI", "F", "E"})
_NUM_INCOMPLETE = frozenset({"AM", "FS", "AE", "ES"})


class JSONStreamDecoder:
    def __init__(self, *, max_buffer: int = 10_000_000) -> None:
        if isinstance(max_buffer, bool) or not isinstance(max_buffer, int) or max_buffer < 1:
            raise ValueError("max_buffer must be an int >= 1")
        self.max_buffer: int = max_buffer
        self._total: int = 0
        self._state: str = "IDLE"  # IDLE | TOP_NUM | TOP_LIT | IN_VALUE | CLOSED | ERROR
        self._buf: list[str] = []
        self._vs: int = 0  # absolute offset of value start
        self._depth: int = 0
        self._stack: list[tuple[str, str]] = []  # (type 'o'/'a', sub-state)
        self._instr: bool = False
        self._strst: str = "N"  # N=normal, E=escape, U=unicode
        self._u_rem: int = 0
        self._numst: str = ""
        self._littgt: str = ""
        self._litpos: int = 0
        self._nested_num: bool = False
        self._nested_lit: bool = False

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def feed(self, chunk: str) -> list[Any]:
        if self._state in ("CLOSED", "ERROR"):
            raise JSONStreamError("decoder is unusable after close/error", self._total)
        if not isinstance(chunk, str):
            raise TypeError(f"expected str, got {type(chunk).__name__}")
        results: list[Any] = []
        for ch in chunk:
            off = self._total
            self._total += 1
            self._process(ch, off, results)
        return results

    def close(self) -> list[Any]:
        if self._state in ("CLOSED", "ERROR"):
            raise JSONStreamError("decoder is unusable after close/error", self._total)
        if self._state == "IDLE":
            self._state = "CLOSED"
            return []
        if self._state == "TOP_NUM":
            if self._numst in _NUM_VALID:
                self._state = "CLOSED"
                return [json.loads("".join(self._buf))]
            self._state = "CLOSED"
            raise IncompleteJSONError("incomplete number", self._total)
        if self._state == "TOP_LIT":
            if self._litpos >= len(self._littgt):
                self._state = "CLOSED"
                return [json.loads("".join(self._buf))]
            self._state = "CLOSED"
            raise IncompleteJSONError("incomplete literal", self._total)
        # IN_VALUE: open string / container / nested value in progress
        self._state = "CLOSED"
        raise IncompleteJSONError("incomplete value", self._total)

    def pending(self) -> int:
        if self._state in ("CLOSED", "ERROR"):
            return 0
        if self._state == "IDLE":
            return 0
        return len(self._buf)

    # ------------------------------------------------------------------
    # Dispatcher
    # ------------------------------------------------------------------

    def _process(self, ch: str, off: int, results: list[Any]) -> None:
        st = self._state
        if st == "IDLE":
            self._idle(ch, off, results)
        elif st == "TOP_NUM":
            self._top_num(ch, off, results)
        elif st == "TOP_LIT":
            self._top_lit(ch, off, results)
        elif st == "IN_VALUE":
            self._in_value(ch, off, results)

    # ------------------------------------------------------------------
    # IDLE
    # ------------------------------------------------------------------

    def _idle(self, ch: str, off: int, results: list[Any]) -> None:
        if ch in _WS:
            return
        if ch == "{":
            self._begin_value(ch, off)
            self._depth = 1
            self._stack = [("o", "OS")]
            self._state = "IN_VALUE"
        elif ch == "[":
            self._begin_value(ch, off)
            self._depth = 1
            self._stack = [("a", "AS")]
            self._state = "IN_VALUE"
        elif ch == '"':
            self._begin_value(ch, off)
            self._instr = True
            self._strst = "N"
            self._state = "IN_VALUE"
        elif ch == "-":
            self._begin_value(ch, off)
            self._numst = "AM"
            self._state = "TOP_NUM"
        elif "0" <= ch <= "9":
            self._begin_value(ch, off)
            self._numst = "AZ" if ch == "0" else "AI"
            self._state = "TOP_NUM"
        elif ch == "t":
            self._begin_value(ch, off)
            self._littgt = "true"
            self._litpos = 1
            self._state = "TOP_LIT"
        elif ch == "f":
            self._begin_value(ch, off)
            self._littgt = "false"
            self._litpos = 1
            self._state = "TOP_LIT"
        elif ch == "n":
            self._begin_value(ch, off)
            self._littgt = "null"
            self._litpos = 1
            self._state = "TOP_LIT"
        else:
            self._error(off)

    # ------------------------------------------------------------------
    # TOP-level number / literal
    # ------------------------------------------------------------------

    def _top_num(self, ch: str, off: int, results: list[Any]) -> None:
        cont = self._num_continue(ch)
        if cont is not None:
            self._append(ch, off)
            self._numst = cont
            return
        # Cannot continue – number must be valid to be emitted
        if self._numst in _NUM_INCOMPLETE:
            self._error(off)
        # Terminator check
        if ch in _WS:
            self._emit_top(results)
            self._state = "IDLE"
        elif ch in ("{", "[", '"'):
            self._emit_top(results)
            self._idle(ch, off, results)  # start new value
        else:
            self._error(off)

    def _top_lit(self, ch: str, off: int, results: list[Any]) -> None:
        if self._litpos < len(self._littgt):
            if ch == self._littgt[self._litpos]:
                self._append(ch, off)
                self._litpos += 1
                return
            # Mismatch: literal cannot complete
            self._error(off)
        # Literal text complete – terminator check
        if ch in _WS:
            self._emit_top(results)
            self._state = "IDLE"
        elif ch in ("{", "[", '"'):
            self._emit_top(results)
            self._idle(ch, off, results)
        else:
            self._error(off)

    # ------------------------------------------------------------------
    # IN_VALUE (string / container)
    # ------------------------------------------------------------------

    def _in_value(self, ch: str, off: int, results: list[Any]) -> None:
        self._append(ch, off)
        if self._instr:
            self._str_char(ch, off, results)
        elif self._nested_num:
            self._nested_num_char(ch, off, results)
        elif self._nested_lit:
            self._nested_lit_char(ch, off, results)
        else:
            self._container_char(ch, off, results)

    # ------------------------------------------------------------------
    # String scanning (shared for top-level and nested)
    # ------------------------------------------------------------------

    def _str_char(self, ch: str, off: int, results: list[Any]) -> None:
        if self._strst == "N":
            if ch == '"':
                self._instr = False
                self._on_string_end(off, results)
            elif ch == "\\":
                self._strst = "E"
            elif ord(ch) < 0x20:
                self._error(off)
        elif self._strst == "E":
            if ch in ('"', "\\", "/", "b", "f", "n", "r", "t"):
                self._strst = "N"
            elif ch == "u":
                self._strst = "U"
                self._u_rem = 4
            else:
                self._error(off)
        elif self._strst == "U":
            if ch in _HEX:
                self._u_rem -= 1
                if self._u_rem == 0:
                    self._strst = "N"
            else:
                self._error(off)

    def _on_string_end(self, off: int, results: list[Any]) -> None:
        if self._depth == 0:
            results.append(json.loads("".join(self._buf)))
            self._buf = []
            self._state = "IDLE"
        else:
            typ, st = self._stack[-1]
            if typ == "o" and st in ("OS", "OC"):
                self._stack[-1] = ("o", "KE")
            elif typ == "o" and st == "AC":
                self._stack[-1] = ("o", "AV")
            elif typ == "a":
                self._stack[-1] = ("a", "AV")

    # ------------------------------------------------------------------
    # Nested number / literal inside containers
    # ------------------------------------------------------------------

    def _nested_num_char(self, ch: str, off: int, results: list[Any]) -> None:
        cont = self._num_continue(ch)
        if cont is not None:
            self._numst = cont
            return
        if self._numst in _NUM_INCOMPLETE:
            self._error(off)
        self._nested_num = False
        typ, st = self._stack[-1]
        self._stack[-1] = (typ, "AV")
        self._delim(ch, off, results)

    def _nested_lit_char(self, ch: str, off: int, results: list[Any]) -> None:
        if self._litpos < len(self._littgt):
            if ch == self._littgt[self._litpos]:
                self._litpos += 1
                return
            self._error(off)
        self._nested_lit = False
        typ, st = self._stack[-1]
        self._stack[-1] = (typ, "AV")
        self._delim(ch, off, results)

    # ------------------------------------------------------------------
    # Container structural scanner
    # ------------------------------------------------------------------

    def _container_char(self, ch: str, off: int, results: list[Any]) -> None:
        typ, st = self._stack[-1]
        if ch in _WS:
            return
        if typ == "o":
            if st == "OS":
                if ch == "}":
                    self._close_cont(off, results)
                elif ch == '"':
                    self._instr = True
                    self._strst = "N"
                else:
                    self._error(off)
            elif st == "KE":
                if ch == ":":
                    self._stack[-1] = ("o", "AC")
                else:
                    self._error(off)
            elif st == "AC":
                self._start_nested(ch, off, results)
            elif st == "AV":
                if ch == ",":
                    self._stack[-1] = ("o", "OC")
                elif ch == "}":
                    self._close_cont(off, results)
                else:
                    self._error(off)
            elif st == "OC":
                if ch == '"':
                    self._instr = True
                    self._strst = "N"
                else:
                    self._error(off)
        else:  # 'a'
            if st == "AS":
                if ch == "]":
                    self._close_cont(off, results)
                else:
                    self._start_nested(ch, off, results)
            elif st == "AV":
                if ch == ",":
                    self._stack[-1] = ("a", "AC")
                elif ch == "]":
                    self._close_cont(off, results)
                else:
                    self._error(off)
            elif st == "AC":
                if ch == "]":
                    self._error(off)  # trailing comma
                else:
                    self._start_nested(ch, off, results)

    def _start_nested(self, ch: str, off: int, results: list[Any]) -> None:
        if ch == "{":
            self._depth += 1
            self._stack.append(("o", "OS"))
        elif ch == "[":
            self._depth += 1
            self._stack.append(("a", "AS"))
        elif ch == '"':
            self._instr = True
            self._strst = "N"
        elif ch == "-":
            self._nested_num = True
            self._numst = "AM"
        elif "0" <= ch <= "9":
            self._nested_num = True
            self._numst = "AZ" if ch == "0" else "AI"
        elif ch == "t":
            self._nested_lit = True
            self._littgt = "true"
            self._litpos = 1
        elif ch == "f":
            self._nested_lit = True
            self._littgt = "false"
            self._litpos = 1
        elif ch == "n":
            self._nested_lit = True
            self._littgt = "null"
            self._litpos = 1
        else:
            self._error(off)

    def _delim(self, ch: str, off: int, results: list[Any]) -> None:
        typ, st = self._stack[-1]
        if ch in _WS:
            return
        if ch == ",":
            self._stack[-1] = (typ, "OC" if typ == "o" else "AC")
        elif ch == "}":
            if typ == "o":
                self._close_cont(off, results)
            else:
                self._error(off)
        elif ch == "]":
            if typ == "a":
                self._close_cont(off, results)
            else:
                self._error(off)
        else:
            self._error(off)

    def _close_cont(self, off: int, results: list[Any]) -> None:
        self._stack.pop()
        self._depth -= 1
        if self._depth == 0:
            results.append(json.loads("".join(self._buf)))
            self._buf = []
            self._state = "IDLE"
        else:
            typ, st = self._stack[-1]
            self._stack[-1] = (typ, "AV")

    # ------------------------------------------------------------------
    # Helpers
    # ------------------------------------------------------------------

    def _num_continue(self, ch: str) -> str | None:
        st = self._numst
        if st == "AM":
            if ch == "0":
                return "AZ"
            if "1" <= ch <= "9":
                return "AI"
            return None
        if st == "AZ":
            if ch == ".":
                return "FS"
            if ch in ("e", "E"):
                return "AE"
            return None
        if st == "AI":
            if "0" <= ch <= "9":
                return "AI"
            if ch == ".":
                return "FS"
            if ch in ("e", "E"):
                return "AE"
            return None
        if st == "FS":
            if "0" <= ch <= "9":
                return "F"
            return None
        if st == "F":
            if "0" <= ch <= "9":
                return "F"
            if ch in ("e", "E"):
                return "AE"
            return None
        if st == "AE":
            if ch in ("+", "-"):
                return "ES"
            if "0" <= ch <= "9":
                return "E"
            return None
        if st == "ES":
            if "0" <= ch <= "9":
                return "E"
            return None
        if st == "E":
            if "0" <= ch <= "9":
                return "E"
            return None
        return None

    def _begin_value(self, ch: str, off: int) -> None:
        self._buf = [ch]
        self._vs = off
        if len(self._buf) > self.max_buffer:
            self._buffer_limit(off)

    def _append(self, ch: str, off: int) -> None:
        self._buf.append(ch)
        if len(self._buf) > self.max_buffer:
            self._buffer_limit(off)

    def _emit_top(self, results: list[Any]) -> None:
        results.append(json.loads("".join(self._buf)))
        self._buf = []

    def _error(self, off: int) -> None:
        self._state = "ERROR"
        exc = JSONStreamError("invalid JSON")
        exc.offset = off
        raise exc

    def _buffer_limit(self, off: int) -> None:
        self._state = "ERROR"
        exc = BufferLimitError("buffer limit exceeded")
        exc.offset = self._vs + self.max_buffer
        raise exc
