```python
"""Comprehensive pytest suite for solution.JSONStreamDecoder."""

import json
import pytest
import solution
from solution import JSONStreamDecoder, JSONStreamError, IncompleteJSONError, BufferLimitError


# ─── Construction ────────────────────────────────────────────────────────────

class TestConstruction:
    def test_default_max_buffer(self):
        d = JSONStreamDecoder()
        assert d.max_buffer == 10_000_000

    def test_custom_max_buffer(self):
        d = JSONStreamDecoder(max_buffer=100)
        assert d.max_buffer == 100

    def test_invalid_max_buffer_zero(self):
        with pytest.raises(ValueError):
            JSONStreamDecoder(max_buffer=0)

    def test_invalid_max_buffer_negative(self):
        with pytest.raises(ValueError):
            JSONStreamDecoder(max_buffer=-1)

    def test_invalid_max_buffer_float(self):
        with pytest.raises(ValueError):
            JSONStreamDecoder(max_buffer=3.5)

    def test_invalid_max_buffer_bool(self):
        with pytest.raises(ValueError):
            JSONStreamDecoder(max_buffer=True)


# ─── feed() type check ───────────────────────────────────────────────────────

class TestFeedTypeCheck:
    def test_feed_non_string_raises_type_error(self):
        d = JSONStreamDecoder()
        with pytest.raises(TypeError):
            d.feed(b"123")  # type: ignore

    def test_feed_none_raises_type_error(self):
        d = JSONStreamDecoder()
        with pytest.raises(TypeError):
            d.feed(None)  # type: ignore

    def test_feed_int_raises_type_error(self):
        d = JSONStreamDecoder()
        with pytest.raises(TypeError):
            d.feed(42)  # type: ignore

    def test_feed_empty_string_ok(self):
        d = JSONStreamDecoder()
        assert d.feed("") == []


# ─── Basic values ────────────────────────────────────────────────────────────

class TestBasicValues:
    def test_integer(self):
        d = JSONStreamDecoder()
        assert d.feed("42 ") == [42]

    def test_negative_integer(self):
        d = JSONStreamDecoder()
        assert d.feed("-7 ") == [-7]

    def test_zero(self):
        d = JSONStreamDecoder()
        assert d.feed("0 ") == [0]

    def test_float(self):
        d = JSONStreamDecoder()
        assert d.feed("3.14 ") == [3.14]

    def test_negative_zero_float(self):
        d = JSONStreamDecoder()
        result = d.feed("-0.0 ")
        assert result == [-0.0]
        import math
        assert math.copysign(1, result[0]) == -1

    def test_exponent(self):
        d = JSONStreamDecoder()
        assert d.feed("1E10 ") == [1e10]

    def test_exponent_large(self):
        d = JSONStreamDecoder()
        assert d.feed("1E400 ") == [float("inf")]

    def test_true(self):
        d = JSONStreamDecoder()
        assert d.feed("true ") == [True]

    def test_false(self):
        d = JSONStreamDecoder()
        assert d.feed("false ") == [False]

    def test_null(self):
        d = JSONStreamDecoder()
        assert d.feed("null ") == [None]

    def test_string(self):
        d = JSONStreamDecoder()
        assert d.feed('"hello"') == ["hello"]

    def test_empty_string(self):
        d = JSONStreamDecoder()
        assert d.feed('""') == [""]

    def test_empty_object(self):
        d = JSONStreamDecoder()
        assert d.feed("{}") == [{}]

    def test_empty_array(self):
        d = JSONStreamDecoder()
        assert d.feed("[]") == [[]]

    def test_object_with_keys(self):
        d = JSONStreamDecoder()
        assert d.feed('{"a":1,"b":[2,3]}') == [{"a": 1, "b": [2, 3]}]

    def test_nested_containers(self):
        d = JSONStreamDecoder()
        assert d.feed('{"x":{"y":[1,{"z":true}]}}') == [{"x": {"y": [1, {"z": True}]}}]

    def test_string_escapes(self):
        d = JSONStreamDecoder()
        result = d.feed(r'"a\"b\/c\\d\ne\tf\rg\bh"' + " ")
        assert result == ['a"b/c\\d\ne\tf\rg\bb']

    def test_unicode_escape(self):
        d = JSONStreamDecoder()
        assert d.feed('"\\u00e9"') == ["é"]

    def test_unicode_escape_surrogate_pair(self):
        d = JSONStreamDecoder()
        assert d.feed('"\\ud83d\\ude00"') == ["😀"]

    def test_lone_surrogate_accepted(self):
        d = JSONStreamDecoder()
        result = d.feed('"\\ud800"')
        assert len(result) == 1
        assert len(result[0]) == 1

    def test_uppercase_hex_escape(self):
        d = JSONStreamDecoder()
        assert d.feed('"\\u00FF"') == ["ÿ"]

    def test_large_integer(self):
        d = JSONStreamDecoder()
        big = "123456789012345678901234567890"
        assert d.feed(big + " ") == [int(big)]

    def test_duplicate_keys_last_wins(self):
        d = JSONStreamDecoder()
        assert d.feed('{"a":1,"a":2}') == [{"a": 2}]

    def test_key_order_preserved(self):
        d = JSONStreamDecoder()
        result = d.feed('{"b":1,"a":2}')
        assert list(result[0].keys()) == ["b", "a"]


# ─── Multiple values, no-whitespace separation ───────────────────────────────

class TestMultipleValues:
    def test_no_whitespace_between(self):
        d = JSONStreamDecoder()
        assert d.feed('{}[]1"x"true') == [{}, [], None, "x", True]
        # close to flush the trailing true? No – "true" needs terminator.
        # Actually "true" at end has no terminator yet.
        # Let me re-check: feed('{}[]1"x"true')
        # {} -> complete. [] -> complete. 1 -> TOP_NUM, needs terminator.
        # "x" -> string complete. true -> TOP_LIT, needs terminator.
        # So results = [{}, [], "x"]. 1 and true are pending.
        # Let me fix this test.

    def test_no_whitespace_complete(self):
        d = JSONStreamDecoder()
        results = d.feed('{}[]"x"')
        assert results == [{}, [], "x"]

    def test_1_2_separated(self):
        d = JSONStreamDecoder()
        assert d.feed("1 2 ") == [1, 2]

    def test_12_one_value(self):
        d = JSONStreamDecoder()
        assert d.feed("12 ") == [12]

    def test_values_in_one_chunk(self):
        d = JSONStreamDecoder()
        assert d.feed("1 2 3 true false null") == []
        # true, false, null need terminators. Let's close:
        r = d.close()
        assert r == [None]
        # Actually: "1 2 3 true false null" -> 1,2,3 emitted. true/false/null pending.
        # After feed: [1,2,3]. close() -> returns null (last pending).
        # Let me restructure.

    def test_values_with_trailing_whitespace(self):
        d = JSONStreamDecoder()
        assert d.feed("1 2 3 true false null ") == [1, 2, 3, True, False, None]

    def test_object_array_string_adjacent(self):
        d = JSONStreamDecoder()
        assert d.feed('{}[]"x"') == [{}, [], "x"]

    def test_number_then_object(self):
        d = JSONStreamDecoder()
        assert d.feed('1{"a":2}') == [1, {"a": 2}]

    def test_number_then_array(self):
        d = JSONStreamDecoder()
        assert d.feed("1[2]") == [1, [2]]

    def test_number_then_string(self):
        d = JSONStreamDecoder()
        assert d.feed('1"x"') == [1, "x"]

    def test_true_then_string(self):
        d = JSONStreamDecoder()
        assert d.feed('true"x"') == [True, "x"]

    def test_null_then_object(self):
        d = JSONStreamDecoder()
        assert d.feed('null{}') == [None, {}]


# ─── Incremental feeding ─────────────────────────────────────────────────────

class TestIncrementalFeeding:
    def test_number_across_chunks(self):
        d = JSONStreamDecoder()
        assert d.feed("12") == []
        assert d.pending() == 2
        assert d.feed(" ") == [12]

    def test_number_split_mid_digit(self):
        d = JSONStreamDecoder()
        assert d.feed("1") == []
        assert d.feed("2") == []
        assert d.feed(" ") == [12]

    def test_string_split_mid_string(self):
        d = JSONStreamDecoder()
        assert d.feed('"hel') == []
        assert d.pending() == 4  # "hel
        assert d.feed('lo"') == ["hello"]

    def test_escape_split(self):
        d = JSONStreamDecoder()
        assert d.feed('"a\\') == []
        assert d.pending() == 3
        assert d.feed('u00e9"') == ["é"]

    def test_unicode_escape_split(self):
        d = JSONStreamDecoder()
        assert d.feed('"\\u00') == []
        assert d.pending() == 4
        assert d.feed('e9"') == ["é"]

    def test_container_split(self):
        d = JSONStreamDecoder()
        assert d.feed('{"a":') == []
        assert d.pending() == 5
        assert d.feed("1}") == [{"a": 1}]

    def test_deeply_nested_split(self):
        d = JSONStreamDecoder()
        assert d.feed("[[[") == []
        assert d.feed("1]]]") == [[[1]]]

